import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// Imagem da Home incorporada no Dart para funcionar mesmo em projetos
/// que distribuem apenas a pasta lib, sem editar pubspec.yaml.
class HomeHeroImage extends StatelessWidget {
  const HomeHeroImage({super.key});

  static final Uint8List _imageBytes = base64Decode(_encodedImage);

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: double.infinity,
      child: Image.memory(
        _imageBytes,
        height: 235,
        fit: BoxFit.contain,
        gaplessPlayback: true,
        filterQuality: FilterQuality.medium,
        semanticLabel: 'Três conversas ilustrativas em telemóveis',
      ),
    );
  }
}

const String _encodedImage = '''''';
